B.a78=s(["\u5df2\u5b58\u9805\u76ee\u5148\u4f9d\u4f7f\u7528\u6b21\u6578\u53d6\u524d 10 \u540d\uff0c\u518d\u4ee5\u6578\u503c\u3001\u82f1\u6587\u5b57\u6bcd\u8207\u7e41\u4e2d\u7b46\u756b\u9806\u5e8f\u986f\u793a\u3002","\u624b\u6a5f\u7248\u91d1\u984d\u8207\u5e63\u5225\u6539\u70ba\u4e0a\u4e0b\u6392\u5217\uff0c\u91d1\u984d\u984c\u6703\u81ea\u52d5\u53d6\u5f97\u8f38\u5165\u6e38\u6a19\u3002","\u9010\u984c\u65b0\u589e\u5207\u984c\u6642\u81ea\u52d5\u5c07\u76ee\u524d\u8cc7\u8a0a\u5361\u6372\u81f3\u9802\u7aef\uff0c\u6309\u9215\u7c21\u5316\u70ba\u300c\u8fd4\u56de\u300d\u8207\u300c\u7e7c\u7e8c\u300d\u3002"],t.s)
B.ae3=s(["Saved items keep the ten most-used values, then display them in numeric, alphabetical, or Traditional-Chinese stroke order.","Phone amount and currency fields now stack vertically, and the amount field receives input focus automatically.","Each step scrolls its current card to the top, with shorter Back and Continue controls."],t.s)
B.Tw=new A.fC("v1.2.101+109","\u6b77\u53f2\u6392\u884c\u8207\u9010\u984c\u8f38\u5165\u512a\u5316","History sorting and step-by-step entry improvements",B.a78,B.ae3)
